        vm.assume(mtFeeRate <= 10**18);
        vm.prank(c._MAINTAINER_());
        c.adjustMtFeeRate(mtFeeRate);

        (,,, uint256 baseReserve, uint256 quoteReserve, uint256 baseTarget, uint256 quoteTarget, uint256 rState) = c.getPMMStateForCall();
        if (rState == uint256(1)) {
            assertTrue(baseTarget == baseReserve && quoteTarget == quoteReserve);
        } else {
            assertTrue(true);
        }
    }
}

